-- CTR: contract (existing, extended)
ALTER TABLE contract ADD COLUMN IF NOT EXISTS title text;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS advance_category text NOT NULL DEFAULT 'CONSTRUCTION' CHECK (advance_category IN ('CONSTRUCTION','EQUIPMENT','CONSULTING','EPC','LAND_CLEARANCE','OTHER'));
ALTER TABLE contract ADD COLUMN IF NOT EXISTS is_joint_venture boolean NOT NULL DEFAULT false;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS signed_on date;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS effective_from date;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS completion_due date;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS contract_value_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (contract_value_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS estimate_ceiling_vnd numeric(24,0) CHECK (estimate_ceiling_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS current_revision_id uuid;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS accepted_total_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (accepted_total_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS requested_total_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (requested_total_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS paid_total_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (paid_total_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS advance_paid_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (advance_paid_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS advance_recovered_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (advance_recovered_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS advance_outstanding_vnd numeric(24,0) GENERATED ALWAYS AS (advance_paid_vnd - advance_recovered_vnd) STORED;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS retention_held_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (retention_held_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS retention_released_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (retention_released_vnd >= 0);
ALTER TABLE contract ADD COLUMN IF NOT EXISTS requires_quality_acceptance boolean NOT NULL DEFAULT true;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS status_reason text;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS status_decision_document_version_id uuid;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS suspended_from date;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS terminated_on date;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE contract ADD COLUMN IF NOT EXISTS created_by uuid;
ALTER TABLE contract ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE contract ADD COLUMN IF NOT EXISTS updated_by uuid;
ALTER TABLE contract ENABLE ROW LEVEL SECURITY;
ALTER TABLE contract FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON contract;
DROP POLICY IF EXISTS tenant_access ON contract;
