ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','CONTRACTOR_SIGNED','SUPERVISED','OWNER_CONFIRMED','LOCKED','SUPERSEDED'));
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS content_hash char(64);
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS supervisor_remark text;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS weather_code text;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS workforce_count integer CHECK (workforce_count >= 0);
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS correction_of_id uuid;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS correction_reason text;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS conflict_of_id uuid;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS conflict_state text NOT NULL DEFAULT 'NONE' CHECK (conflict_state IN ('NONE','CONFLICT_PENDING','RESOLVED'));
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS device_id uuid;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS locked_at timestamptz;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS created_by uuid;
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE site_diary ADD COLUMN IF NOT EXISTS updated_by uuid;
ALTER TABLE site_diary ENABLE ROW LEVEL SECURITY;
ALTER TABLE site_diary FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON site_diary;
DROP POLICY IF EXISTS tenant_access ON site_diary;
CREATE POLICY tenant_boundary ON site_diary AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON site_diary AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE site_diary ADD CONSTRAINT site_diary_signed_hash_chk CHECK (status = 'DRAFT' OR content_hash IS NOT NULL);
ALTER TABLE site_diary ADD CONSTRAINT site_diary_correction_chk CHECK ((correction_of_id IS NULL) = (correction_reason IS NULL));
ALTER TABLE site_diary ADD CONSTRAINT site_diary_conflict_chk CHECK ((conflict_of_id IS NULL) = (conflict_state = 'NONE'));
ALTER TABLE site_diary ADD CONSTRAINT site_diary_locked_chk CHECK (status <> 'LOCKED' OR locked_at IS NOT NULL);
CREATE UNIQUE INDEX site_diary_day_uq ON site_diary (tenant_id, contract_id, record_date) WHERE correction_of_id IS NULL AND conflict_of_id IS NULL AND status <> 'SUPERSEDED';

-- QMS: qms_signature
CREATE TABLE qms_signature (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  subject_kind text NOT NULL CHECK (subject_kind IN ('SITE_DIARY','INSPECTION','QUALITY_ACCEPTANCE','MATERIAL_TEST','CORRECTIVE_ACTION')),
  subject_id uuid NOT NULL,
  signer_role text NOT NULL CHECK (signer_role IN ('CONTRACTOR','SUPERVISOR','OWNER','DESIGNER','TESTING_LAB','OTHER')),
  membership_id uuid NOT NULL,
  signer_name_snapshot text NOT NULL,
  method text NOT NULL CHECK (method IN ('IN_APP_OTP','IN_APP_WEBAUTHN','DIGITAL_CERT')),
  legal_effect text NOT NULL CHECK (legal_effect IN ('INTERNAL_RECORD','LEGAL_E_SIGNATURE')),
  cert_serial text,
  signed_content_hash char(64) NOT NULL,
  signed_at timestamptz NOT NULL,
  device_id uuid,
  client_operation_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE qms_signature ENABLE ROW LEVEL SECURITY;
ALTER TABLE qms_signature FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON qms_signature;
DROP POLICY IF EXISTS tenant_access ON qms_signature;
CREATE POLICY tenant_boundary ON qms_signature AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON qms_signature AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE qms_signature ADD CONSTRAINT qms_signature_cert_chk CHECK (method <> 'DIGITAL_CERT' OR cert_serial IS NOT NULL);
ALTER TABLE qms_signature ADD CONSTRAINT qms_signature_effect_chk CHECK ((method = 'DIGITAL_CERT') = (legal_effect = 'LEGAL_E_SIGNATURE'));
CREATE UNIQUE INDEX qms_signature_once_uq ON qms_signature (tenant_id, subject_kind, subject_id, signer_role, signed_content_hash);
CREATE UNIQUE INDEX qms_signature_op_uq ON qms_signature (tenant_id, client_operation_id);
REVOKE UPDATE, DELETE ON qms_signature FROM PUBLIC;

-- QMS: site_photo
CREATE TABLE site_photo (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  contract_id uuid,
  site_diary_id uuid,
  inspection_id uuid,
  nonconformance_id uuid,
  issue_id uuid,
  client_operation_id uuid NOT NULL,
  object_key text NOT NULL,
  file_sha256 char(64) NOT NULL,
  scan_status text NOT NULL DEFAULT 'PENDING' CHECK (scan_status IN ('PENDING','CLEAN','INFECTED')),
  taken_at_exif timestamptz,
  received_at timestamptz NOT NULL DEFAULT now(),
  gps_lat numeric(9,6),
  gps_lng numeric(9,6),
  gps_accuracy_m numeric(8,2),
  gps_source text NOT NULL DEFAULT 'NONE' CHECK (gps_source IN ('EXIF','DEVICE_AT_CAPTURE','MANUAL','NONE')),
  geo_consent boolean NOT NULL DEFAULT false,
  device_id uuid,
  device_model text,
  check_time text NOT NULL DEFAULT 'MISSING' CHECK (check_time IN ('OK','SKEW','MISSING')),
  check_geofence text NOT NULL DEFAULT 'MISSING' CHECK (check_geofence IN ('INSIDE','OUTSIDE','LOW_ACCURACY','MISSING')),
  check_duplicate text NOT NULL DEFAULT 'UNIQUE' CHECK (check_duplicate IN ('UNIQUE','DUPLICATE_SAME_SITE','DUPLICATE_OTHER_SITE')),
  check_exif text NOT NULL DEFAULT 'STRIPPED' CHECK (check_exif IN ('CONSISTENT','STRIPPED','INCONSISTENT')),
  check_summary text NOT NULL DEFAULT 'WARN' CHECK (check_summary IN ('PASS','WARN','FAIL')),
  caption text,
  uploaded_by uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE site_photo ENABLE ROW LEVEL SECURITY;
ALTER TABLE site_photo FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON site_photo;
DROP POLICY IF EXISTS tenant_access ON site_photo;
CREATE POLICY tenant_boundary ON site_photo AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON site_photo AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE site_photo ADD CONSTRAINT site_photo_geo_consent_chk CHECK (gps_lat IS NULL OR geo_consent OR gps_source = 'EXIF');
CREATE UNIQUE INDEX site_photo_op_uq ON site_photo (tenant_id, client_operation_id);

-- QMS: inspection
CREATE TABLE inspection (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  contract_id uuid NOT NULL,
  boq_item_id uuid,
  inspection_no text NOT NULL,
  inspection_type text NOT NULL CHECK (inspection_type IN ('MATERIAL_ENTRY','CONCEALED_WORK','CONSTRUCTION_STAGE','PART_ACCEPTANCE','COMPLETION','SAFETY','OTHER')),
  title text NOT NULL,
  location_text text,
  requested_by uuid NOT NULL,
  requested_for date NOT NULL,
  scheduled_at timestamptz,
  status text NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','SCHEDULED','RESULT_RECORDED','CANCELLED')),
  result text CHECK (result IN ('PASS','FAIL','CONDITIONAL')),
  result_note text,
  result_recorded_by uuid,
  result_recorded_at timestamptz,
  checklist jsonb NOT NULL DEFAULT '[]'::jsonb,
  regime_rule_version_id uuid,
  site_diary_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE inspection ENABLE ROW LEVEL SECURITY;
ALTER TABLE inspection FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON inspection;
DROP POLICY IF EXISTS tenant_access ON inspection;
CREATE POLICY tenant_boundary ON inspection AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON inspection AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE inspection ADD CONSTRAINT inspection_result_chk CHECK (status <> 'RESULT_RECORDED' OR (result IS NOT NULL AND result_recorded_by IS NOT NULL AND result_recorded_at IS NOT NULL));
CREATE UNIQUE INDEX inspection_no_uq ON inspection (tenant_id, contract_id, inspection_no);

-- QMS: quality_acceptance
