  document_version_id uuid,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SIGNING','APPROVED','REJECTED','REVOKED')),
  required_roles jsonb NOT NULL,
  decision_note text,
  approved_at timestamptz,
  approved_by uuid,
  regime_rule_version_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE quality_acceptance ENABLE ROW LEVEL SECURITY;
ALTER TABLE quality_acceptance FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON quality_acceptance;
DROP POLICY IF EXISTS tenant_access ON quality_acceptance;
CREATE POLICY tenant_boundary ON quality_acceptance AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON quality_acceptance AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE quality_acceptance ADD CONSTRAINT quality_acceptance_approved_chk CHECK (status <> 'APPROVED' OR (document_version_id IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL));
CREATE UNIQUE INDEX quality_acceptance_no_uq ON quality_acceptance (tenant_id, contract_id, record_no);

