CREATE POLICY tenant_boundary ON material_test AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON material_test AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE material_test ADD CONSTRAINT material_test_result_chk CHECK (status = 'REGISTERED' OR (result <> 'PENDING' AND tested_on IS NOT NULL AND report_document_version_id IS NOT NULL));
CREATE UNIQUE INDEX material_test_sample_uq ON material_test (tenant_id, contract_id, sample_code);

-- QMS: quality_nonconformance (existing, extended)
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS ncr_no text;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS title text;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS source_kind text CHECK (source_kind IN ('INSPECTION','MATERIAL_TEST','SUPERVISOR_REMARK','SELF_REPORT','AUDIT'));
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS inspection_id uuid;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS material_test_id uuid;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS site_diary_id uuid;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS detected_on date;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS root_cause text;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS blocks_acceptance boolean NOT NULL DEFAULT false;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS verified_by uuid;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS verified_at timestamptz;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS closed_by uuid;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS closed_at timestamptz;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS version bigint NOT NULL DEFAULT 1;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS created_by uuid;
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE quality_nonconformance ADD COLUMN IF NOT EXISTS updated_by uuid;
ALTER TABLE quality_nonconformance ENABLE ROW LEVEL SECURITY;
ALTER TABLE quality_nonconformance FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON quality_nonconformance;
DROP POLICY IF EXISTS tenant_access ON quality_nonconformance;
CREATE POLICY tenant_boundary ON quality_nonconformance AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON quality_nonconformance AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE quality_nonconformance ADD CONSTRAINT ncr_critical_blocks_chk CHECK (severity <> 'CRITICAL' OR blocks_acceptance);
ALTER TABLE quality_nonconformance ADD CONSTRAINT ncr_verifier_chk CHECK (verified_by IS NULL OR verified_by <> action_owner_id);
ALTER TABLE quality_nonconformance ADD CONSTRAINT ncr_closed_chk CHECK (status <> 'CLOSED' OR (verified_by IS NOT NULL AND closed_by IS NOT NULL AND closed_at IS NOT NULL));
ALTER TABLE quality_nonconformance ADD CONSTRAINT quality_nonconformance_severity_chk CHECK (severity IN ('MINOR','MAJOR','CRITICAL'));
ALTER TABLE quality_nonconformance ADD CONSTRAINT quality_nonconformance_status_chk CHECK (status IN ('OPEN','ACTION_ASSIGNED','ACTION_SUBMITTED','VERIFIED','CLOSED','REOPENED'));
CREATE UNIQUE INDEX ncr_no_uq ON quality_nonconformance (tenant_id, contract_id, ncr_no) WHERE ncr_no IS NOT NULL;

-- QMS: corrective_action
CREATE TABLE corrective_action (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  nonconformance_id uuid NOT NULL,
  description text NOT NULL,
  owner_membership_id uuid NOT NULL,
  due_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'ASSIGNED' CHECK (status IN ('ASSIGNED','SUBMITTED','REJECTED','VERIFIED')),
  evidence_document_version_id uuid,
  evidence_photo_id uuid,
  submitted_at timestamptz,
  verified_by uuid,
  verified_at timestamptz,
  verification_note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE corrective_action ENABLE ROW LEVEL SECURITY;
ALTER TABLE corrective_action FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON corrective_action;
DROP POLICY IF EXISTS tenant_access ON corrective_action;
CREATE POLICY tenant_boundary ON corrective_action AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON corrective_action AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE corrective_action ADD CONSTRAINT corrective_action_verify_chk CHECK (status <> 'VERIFIED' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL AND (evidence_document_version_id IS NOT NULL OR evidence_photo_id IS NOT NULL)));
ALTER TABLE corrective_action ADD CONSTRAINT corrective_action_independent_chk CHECK (verified_by IS NULL OR verified_by <> owner_membership_id);

-- PMT: permit_type
CREATE TABLE permit_type (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  code text NOT NULL,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  name text NOT NULL,
  category text NOT NULL CHECK (category IN ('ENVIRONMENT','DESIGN_APPRAISAL','FIRE_SAFETY','CONSTRUCTION_PERMIT','LAND','TRAFFIC','WATER_RESOURCES','OTHER')),
  authority_text text NOT NULL,
  legal_basis text NOT NULL,
  cxn_ref text,
  effective_from date NOT NULL,
  effective_until date,
  applies_to_rule jsonb NOT NULL,
  default_validity_months integer CHECK (default_validity_months > 0),
  default_processing_days integer CHECK (default_processing_days > 0),
  exemption_allowed boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
  supersedes_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE permit_type ENABLE ROW LEVEL SECURITY;
ALTER TABLE permit_type FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON permit_type;
DROP POLICY IF EXISTS tenant_access ON permit_type;
CREATE POLICY tenant_boundary ON permit_type AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON permit_type AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE permit_type ADD CONSTRAINT permit_type_dates_chk CHECK (effective_until IS NULL OR effective_from < effective_until);
CREATE UNIQUE INDEX permit_type_rev_uq ON permit_type (tenant_id, code, revision);
CREATE UNIQUE INDEX permit_type_published_uq ON permit_type (tenant_id, code) WHERE status = 'PUBLISHED';

-- PMT: permit_dossier
CREATE TABLE permit_dossier (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  project_component_id uuid,
  owner_unit_id uuid NOT NULL,
  owner_membership_id uuid,
  status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','COMPLETE','CLOSED')),
  readiness_pct numeric(5,2) NOT NULL DEFAULT 0 CHECK (readiness_pct BETWEEN 0 AND 100),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE permit_dossier ENABLE ROW LEVEL SECURITY;
ALTER TABLE permit_dossier FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON permit_dossier;
DROP POLICY IF EXISTS tenant_access ON permit_dossier;
CREATE POLICY tenant_boundary ON permit_dossier AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON permit_dossier AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE UNIQUE INDEX permit_dossier_scope_uq ON permit_dossier (tenant_id, project_id, project_component_id) NULLS NOT DISTINCT;

-- PMT: permit
CREATE TABLE permit (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  dossier_id uuid NOT NULL,
  permit_type_id uuid NOT NULL,
  permit_no text,
  status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','SUBMITTED','IN_APPRAISAL','SUPPLEMENT_REQUESTED','ISSUED','REJECTED','EXPIRED','REVOKED','SUPERSEDED','EXEMPTED')),
  authority_name text,
  submitted_on date,
  expected_decision_on date,
  issued_on date,
  valid_from date,
  valid_until date,
  no_expiry boolean NOT NULL DEFAULT false,
  exemption_basis text,
  exemption_decision_document_version_id uuid,
  document_version_id uuid,
  supersedes_id uuid,
  responsible_membership_id uuid,
  alert_level_sent smallint NOT NULL DEFAULT 0 CHECK (alert_level_sent BETWEEN 0 AND 4),
  revoke_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE permit ENABLE ROW LEVEL SECURITY;
ALTER TABLE permit FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON permit;
DROP POLICY IF EXISTS tenant_access ON permit;
CREATE POLICY tenant_boundary ON permit AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON permit AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE permit ADD CONSTRAINT permit_issued_chk CHECK (status <> 'ISSUED' OR (permit_no IS NOT NULL AND issued_on IS NOT NULL AND document_version_id IS NOT NULL AND valid_from IS NOT NULL AND (no_expiry OR valid_until IS NOT NULL)));
ALTER TABLE permit ADD CONSTRAINT permit_validity_chk CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_from <= valid_until);
ALTER TABLE permit ADD CONSTRAINT permit_exempt_chk CHECK (status <> 'EXEMPTED' OR (exemption_basis IS NOT NULL AND exemption_decision_document_version_id IS NOT NULL));
ALTER TABLE permit ADD CONSTRAINT permit_revoke_chk CHECK (status <> 'REVOKED' OR revoke_reason IS NOT NULL);
CREATE UNIQUE INDEX permit_type_no_uq ON permit (tenant_id, permit_type_id, permit_no) WHERE permit_no IS NOT NULL;
CREATE UNIQUE INDEX permit_current_uq ON permit (tenant_id, dossier_id, permit_type_id) WHERE status IN ('ISSUED','EXEMPTED');

-- PMT: permit_milestone
CREATE TABLE permit_milestone (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  permit_id uuid NOT NULL,
  step_code text NOT NULL CHECK (step_code IN ('SUBMITTED','ACKNOWLEDGED','APPRAISAL_MEETING','SUPPLEMENT_REQUESTED','SUPPLEMENT_SUBMITTED','DECISION','HANDED_OVER')),
  planned_on date,
  actual_on date,
  note text,
  document_version_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE permit_milestone ENABLE ROW LEVEL SECURITY;
ALTER TABLE permit_milestone FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON permit_milestone;
DROP POLICY IF EXISTS tenant_access ON permit_milestone;
CREATE POLICY tenant_boundary ON permit_milestone AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON permit_milestone AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);

-- PMT: permit_gate_rule
