  permit_type_id uuid NOT NULL,
  requirement text NOT NULL DEFAULT 'VALID_PERMIT' CHECK (requirement IN ('VALID_PERMIT','VALID_OR_EXEMPT','SUBMITTED_ONLY')),
  applies_to_rule jsonb NOT NULL,
  legal_basis text NOT NULL,
  effective_from date NOT NULL,
  effective_until date,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE permit_gate_rule ENABLE ROW LEVEL SECURITY;
ALTER TABLE permit_gate_rule FORCE ROW LEVEL SECURITY;
