CREATE UNIQUE INDEX permit_gate_rule_rev_uq ON permit_gate_rule (tenant_id, gate_code, permit_type_id, revision);
CREATE UNIQUE INDEX permit_gate_rule_published_uq ON permit_gate_rule (tenant_id, gate_code, permit_type_id) WHERE status = 'PUBLISHED';

