-- LND: land_parcel
CREATE TABLE land_parcel (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  section_id uuid,
  owner_unit_id uuid NOT NULL,
  parcel_code text NOT NULL,
  address_text text,
  ward_master_version_id uuid,
  land_use_group text NOT NULL CHECK (land_use_group IN ('AGRICULTURAL','NON_AGRICULTURAL_RESIDENTIAL','NON_AGRICULTURAL_OTHER','PUBLIC')),
  area_total_m2 numeric(14,2) NOT NULL CHECK (area_total_m2 > 0),
  area_affected_m2 numeric(14,2) NOT NULL CHECK (area_affected_m2 >= 0),
  boundary_geojson jsonb,
  status text NOT NULL DEFAULT 'SURVEYED' CHECK (status IN ('SURVEYED','INVENTORIED','PLAN_DRAFTED','PLAN_POSTED','PLAN_APPROVED','PAID','HANDED_OVER','DISPUTED','ENFORCEMENT')),
  recovery_notice_on date,
  notice_days_applied smallint CHECK (notice_days_applied IN (90,180)),
  recovery_decision_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE land_parcel ENABLE ROW LEVEL SECURITY;
ALTER TABLE land_parcel FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON land_parcel;
DROP POLICY IF EXISTS tenant_access ON land_parcel;
CREATE POLICY tenant_boundary ON land_parcel AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON land_parcel AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE land_parcel ADD CONSTRAINT land_parcel_area_chk CHECK (area_affected_m2 <= area_total_m2);
ALTER TABLE land_parcel ADD CONSTRAINT land_parcel_notice_chk CHECK (recovery_decision_on IS NULL OR (recovery_notice_on IS NOT NULL AND notice_days_applied IS NOT NULL AND recovery_decision_on >= recovery_notice_on + notice_days_applied));
CREATE UNIQUE INDEX land_parcel_code_uq ON land_parcel (tenant_id, project_id, parcel_code);

-- LND: affected_household
CREATE TABLE affected_household (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  owner_unit_id uuid NOT NULL,
  household_code text NOT NULL,
  head_name text NOT NULL,
