  policy_beneficiary boolean NOT NULL DEFAULT false,
  legal_basis text NOT NULL CHECK (legal_basis IN ('PUBLIC_TASK_LAND_LAW','LEGAL_OBLIGATION','CONSENT')),
  legal_basis_ref text NOT NULL,
  consent_record_id uuid,
  retention_until date NOT NULL,
  dsr_open boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'REGISTERED' CHECK (status IN ('REGISTERED','INVENTORIED','PLAN_LISTED','COMPENSATED','RESETTLED','CLOSED','DISPUTED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE affected_household ENABLE ROW LEVEL SECURITY;
ALTER TABLE affected_household FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON affected_household;
DROP POLICY IF EXISTS tenant_access ON affected_household;
