CREATE POLICY tenant_access ON affected_household AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
DROP POLICY IF EXISTS scope_units_guard ON affected_household;
CREATE POLICY scope_units_guard ON affected_household AS RESTRICTIVE FOR ALL USING ((current_setting('app.scope_units',true) = '*' OR owner_unit_id::text = ANY(string_to_array(current_setting('app.scope_units',true),',')))) WITH CHECK ((current_setting('app.scope_units',true) = '*' OR owner_unit_id::text = ANY(string_to_array(current_setting('app.scope_units',true),','))));
ALTER TABLE affected_household ADD CONSTRAINT affected_household_consent_chk CHECK (legal_basis <> 'CONSENT' OR consent_record_id IS NOT NULL);
CREATE UNIQUE INDEX affected_household_code_uq ON affected_household (tenant_id, project_id, household_code);
CREATE UNIQUE INDEX affected_household_nid_uq ON affected_household (tenant_id, project_id, national_id_hash) WHERE national_id_hash IS NOT NULL;

