ALTER TABLE land_inventory_record ADD CONSTRAINT land_inventory_confirm_chk CHECK (status <> 'CONFIRMED' OR household_confirmed_on IS NOT NULL);

-- LND: compensation_plan
CREATE TABLE compensation_plan (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  section_id uuid,
  executor_unit_id uuid NOT NULL,
  executor_kind text NOT NULL CHECK (executor_kind IN ('PROJECT_OWNER','LAND_FUND_CENTRE','DISTRICT_BOARD')),
  plan_code text NOT NULL,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  total_compensation_vnd numeric(24,0) NOT NULL DEFAULT 0,
  total_support_vnd numeric(24,0) NOT NULL DEFAULT 0,
  total_resettlement_vnd numeric(24,0) NOT NULL DEFAULT 0,
  grand_total_vnd numeric(24,0) GENERATED ALWAYS AS (total_compensation_vnd + total_support_vnd + total_resettlement_vnd) STORED,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','POSTING','POSTING_CLOSED','APPROVED','PAYING','COMPLETED','CANCELLED','REVISED')),
  posting_started_on date,
  posting_ends_on date,
  posting_place_text text,
  feedback_summary text,
  decision_document_version_id uuid,
  approved_on date,
  payment_due_on date,
  timer_rule_version_id uuid,
  supersedes_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE compensation_plan ENABLE ROW LEVEL SECURITY;
ALTER TABLE compensation_plan FORCE ROW LEVEL SECURITY;
