ALTER TABLE compensation_plan ADD CONSTRAINT compensation_plan_posting_chk CHECK (status NOT IN ('POSTING','POSTING_CLOSED','APPROVED','PAYING','COMPLETED') OR (posting_started_on IS NOT NULL AND posting_ends_on IS NOT NULL AND posting_ends_on >= posting_started_on));
ALTER TABLE compensation_plan ADD CONSTRAINT compensation_plan_approved_chk CHECK (status NOT IN ('APPROVED','PAYING','COMPLETED') OR (approved_on IS NOT NULL AND payment_due_on IS NOT NULL AND decision_document_version_id IS NOT NULL AND approved_on >= posting_ends_on));
CREATE UNIQUE INDEX compensation_plan_rev_uq ON compensation_plan (tenant_id, project_id, plan_code, revision);

