CREATE POLICY tenant_access ON compensation_plan_item AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
DROP POLICY IF EXISTS scope_units_guard ON compensation_plan_item;
