CREATE POLICY tenant_access ON compensation_payment AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
DROP POLICY IF EXISTS scope_units_guard ON compensation_payment;
CREATE POLICY scope_units_guard ON compensation_payment AS RESTRICTIVE FOR ALL USING ((current_setting('app.scope_units',true) = '*' OR owner_unit_id::text = ANY(string_to_array(current_setting('app.scope_units',true),',')))) WITH CHECK ((current_setting('app.scope_units',true) = '*' OR owner_unit_id::text = ANY(string_to_array(current_setting('app.scope_units',true),','))));
ALTER TABLE compensation_payment ADD CONSTRAINT compensation_payment_paid_chk CHECK (status NOT IN ('PAID','DEPOSITED') OR (paid_on IS NOT NULL AND method IS NOT NULL AND voucher_document_version_id IS NOT NULL));
ALTER TABLE compensation_payment ADD CONSTRAINT compensation_payment_deposit_chk CHECK (status <> 'DEPOSITED' OR deposit_reason IS NOT NULL);
CREATE UNIQUE INDEX compensation_payment_uq ON compensation_payment (tenant_id, plan_id, household_id, payment_no);

