-- LND: land_stage_progress
CREATE TABLE land_stage_progress (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  section_id uuid NOT NULL,
  plan_id uuid,
  stage_code text NOT NULL CHECK (stage_code IN ('SURVEY','NOTICE','INVENTORY','PLAN_DRAFT','PLAN_POSTING','PLAN_APPROVAL','PAYMENT','HANDOVER','ENFORCEMENT')),
  executor_kind text NOT NULL CHECK (executor_kind IN ('PROJECT_OWNER','LAND_FUND_CENTRE','DISTRICT_BOARD')),
  executor_unit_id uuid NOT NULL,
  mode text NOT NULL CHECK (mode IN ('NATIVE','TRACKED_EXTERNAL')),
  planned_start date,
  planned_end date,
  actual_start date,
  actual_end date,
  parcels_total integer NOT NULL DEFAULT 0 CHECK (parcels_total >= 0),
  parcels_done integer NOT NULL DEFAULT 0 CHECK (parcels_done >= 0),
  progress_pct numeric(5,2) GENERATED ALWAYS AS (CASE WHEN parcels_total = 0 THEN 0 ELSE round(100.0 * parcels_done / parcels_total, 2) END) STORED,
  last_reported_by uuid,
  last_reported_at timestamptz,
  evidence_document_version_id uuid,
  status text NOT NULL DEFAULT 'NOT_STARTED' CHECK (status IN ('NOT_STARTED','IN_PROGRESS','DONE','BLOCKED','LATE')),
  blocker_issue_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
