ALTER TABLE land_stage_progress ADD CONSTRAINT land_stage_progress_done_chk CHECK (parcels_done <= parcels_total);
ALTER TABLE land_stage_progress ADD CONSTRAINT land_stage_done_chk CHECK (status <> 'DONE' OR actual_end IS NOT NULL);
CREATE UNIQUE INDEX land_stage_progress_uq ON land_stage_progress (tenant_id, section_id, stage_code, plan_id) NULLS NOT DISTINCT;

