-- AST: evaluation_trigger
CREATE TABLE evaluation_trigger (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  project_id uuid NOT NULL,
  trigger_kind text NOT NULL CHECK (trigger_kind IN ('POST_HANDOVER_12M','POST_HANDOVER_24M','SETTLEMENT_CLOSED','MANUAL')),
  source_handover_id uuid,
  due_on date NOT NULL,
  status text NOT NULL DEFAULT 'SCHEDULED' CHECK (status IN ('SCHEDULED','FIRED','ACKNOWLEDGED','CANCELLED')),
  fired_at timestamptz,
  mne_evaluation_id uuid,
  outbox_event_id uuid,
  rule_version_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE evaluation_trigger ENABLE ROW LEVEL SECURITY;
ALTER TABLE evaluation_trigger FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_boundary ON evaluation_trigger;
DROP POLICY IF EXISTS tenant_access ON evaluation_trigger;
CREATE POLICY tenant_boundary ON evaluation_trigger AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_access ON evaluation_trigger AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE evaluation_trigger ADD CONSTRAINT evaluation_trigger_fired_chk CHECK (status NOT IN ('FIRED','ACKNOWLEDGED') OR fired_at IS NOT NULL);
CREATE UNIQUE INDEX evaluation_trigger_uq ON evaluation_trigger (tenant_id, project_id, trigger_kind, source_handover_id) NULLS NOT DISTINCT;

-- Composite tenant-scoped foreign keys
-- Triggers (guards that CHECK cannot express)
CREATE OR REPLACE FUNCTION change_chain_config_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.locked_at IS NOT NULL AND NEW.tier_count <> OLD.tier_count THEN
    RAISE EXCEPTION 'CHANGE_TIERS_LOCKED' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER change_chain_config_guard_tg BEFORE UPDATE ON change_chain_config FOR EACH ROW EXECUTE FUNCTION change_chain_config_guard();
-- CTR: tổng tỷ lệ thành viên liên danh = 100 khi hợp đồng rời DRAFT (constraint trigger deferred)
CREATE OR REPLACE FUNCTION contract_party_share_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE total numeric; st text;
BEGIN
  SELECT status INTO st FROM contract WHERE tenant_id = NEW.tenant_id AND id = NEW.contract_id;
  IF st IS NOT NULL AND st NOT IN ('DRAFT','IN_REVIEW','CANCELLED') THEN
    SELECT COALESCE(SUM(share_pct),0) INTO total FROM contract_party WHERE tenant_id = NEW.tenant_id AND contract_id = NEW.contract_id AND status = 'ACTIVE';
    IF total <> 100 THEN RAISE EXCEPTION 'JV_SHARE_NOT_100' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER contract_party_share_tg AFTER INSERT OR UPDATE ON contract_party DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION contract_party_share_guard();

