-- BEGIN module intelligence
-- Group "intelligence" (DOC, AUD, BID, LLM, BI, DGV) — M1 design, reference only; not executed.
-- RLS convention (04): every tenant table has PERMISSIVE tenant_access + RESTRICTIVE tenant_boundary.
-- Existing owned tables are extended with ALTER TABLE; NOT NULL on new columns of existing tables is applied after backfill.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS vector;
-- DOC: document — sổ văn bản: neo định danh duy nhất của mọi văn bản/tệp hồ sơ; đích FK của các cột *_document_id
CREATE TABLE document (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  doc_kind text NOT NULL CHECK (doc_kind IN ('OUTGOING','INCOMING','REFERENCE','ATTACHMENT')),
  doc_type_code text NOT NULL,
  title text NOT NULL,
  document_number integer CHECK (document_number IS NULL OR document_number > 0),
  number_year integer,
  symbol text,
  issued_on date,
  issuer_unit_id uuid,
  issuer_name text,
  signer_name text,
  signer_title text,
  classification text NOT NULL DEFAULT 'INTERNAL' CHECK (classification IN ('PUBLIC','INTERNAL','CONFIDENTIAL','PERSONAL')),
  effect_status text NOT NULL DEFAULT 'PENDING' CHECK (effect_status IN ('PENDING','EFFECTIVE','RECALLED','REPLACED','CORRECTED','EXPIRED')),
  subject_module text,
  subject_id uuid,
  source_ref text,
  payload_sha256 char(64),
  current_version_id uuid,
  dossier_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document ENABLE ROW LEVEL SECURITY;
ALTER TABLE document FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document ADD CONSTRAINT document_kind_chk CHECK (doc_kind = 'ATTACHMENT' OR effect_status = 'PENDING' OR (symbol IS NOT NULL AND issued_on IS NOT NULL));
ALTER TABLE document ADD CONSTRAINT document_number_chk CHECK (doc_kind NOT IN ('OUTGOING','INCOMING') OR effect_status = 'PENDING' OR (document_number IS NOT NULL AND number_year IS NOT NULL));
ALTER TABLE document ADD CONSTRAINT document_year_chk CHECK (number_year IS NULL OR number_year BETWEEN 2000 AND 2200);
CREATE UNIQUE INDEX document_symbol_out_uq ON document (tenant_id, symbol) WHERE doc_kind = 'OUTGOING' AND symbol IS NOT NULL;
CREATE UNIQUE INDEX document_source_uq ON document (tenant_id, source_ref, payload_sha256) WHERE source_ref IS NOT NULL AND effect_status IN ('PENDING','EFFECTIVE');

-- DOC: document_version (existing, extended)
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS stage text NOT NULL DEFAULT 'ATTACHMENT' CHECK (stage IN ('SOURCE_UPLOAD','RENDERED_FINAL','LEADER_SIGNED','NUMBERED','ORG_SEALED','ISSUED_LTV','RECEIVED_SCAN','ATTACHMENT','CORRECTED_COPY'));
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS byte_length bigint;
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS pdf_revision_count integer;
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS prefix_sha256 char(64);
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS renderer_version text;
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS template_id uuid;
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS supersedes_version_id uuid;
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE document_version ADD COLUMN IF NOT EXISTS created_by uuid;
-- migration: backfill document_version.created_by/stage from audit_event, then SET NOT NULL where applicable
-- migration: baseline v1.3 attached files without a register entry are inserted as document.doc_kind = ATTACHMENT during migration
DROP POLICY IF EXISTS tenant_boundary ON document_version;
CREATE POLICY tenant_access ON document_version AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_version AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_version ADD CONSTRAINT document_version_sha_chk CHECK (checksum ~ '^[0-9a-f]{64}$');
ALTER TABLE document_version ADD CONSTRAINT document_version_rev_chk CHECK (pdf_revision_count IS NULL OR pdf_revision_count >= 1);
CREATE UNIQUE INDEX document_version_doc_ver_uq ON document_version (tenant_id, document_id, version);

-- DOC: doc_type — loại văn bản và quy tắc ký hiệu theo NĐ 30/2020 (dữ liệu, có hiệu lực)
CREATE TABLE doc_type (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  abbreviation text,
  symbol_kind text NOT NULL CHECK (symbol_kind IN ('DECISION','NAMED_TYPE','OFFICIAL_LETTER')),
  symbol_pattern text NOT NULL,
  register_code text NOT NULL,
  legal_basis text NOT NULL,
  legal_confirmation_ref text,
  effective_from date NOT NULL,
  effective_until date,
  status text NOT NULL DEFAULT 'PUBLISHED' CHECK (status IN ('DRAFT','PUBLISHED','SUPERSEDED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE doc_type ENABLE ROW LEVEL SECURITY;
ALTER TABLE doc_type FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON doc_type AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON doc_type AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE doc_type ADD CONSTRAINT doc_type_range_chk CHECK (effective_until IS NULL OR effective_until > effective_from);
CREATE UNIQUE INDEX doc_type_code_from_uq ON doc_type (tenant_id, code, effective_from);

-- DOC: document_layout_profile — bố cục thể thức theo NĐ 30/2020 Phụ lục I dạng dữ liệu (khổ giấy, lề, font, cỡ chữ từng thành phần, vị trí chữ ký/dấu)
CREATE TABLE document_layout_profile (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  profile_code text NOT NULL,
  revision integer NOT NULL CHECK (revision > 0),
  page_size text NOT NULL DEFAULT 'A4' CHECK (page_size = 'A4'),
  margins_mm jsonb NOT NULL,
  font_family text NOT NULL DEFAULT 'Times New Roman',
  font_substitute text,
  element_styles jsonb NOT NULL,
  signature_layout jsonb NOT NULL,
  number_field_layout jsonb NOT NULL,
  watermark_policy jsonb NOT NULL,
  legal_basis text NOT NULL,
  legal_confirmation_ref text,
  confirmation_status text NOT NULL DEFAULT 'PENDING_CONFIRMATION' CHECK (confirmation_status IN ('CONFIRMED','PENDING_CONFIRMATION')),
  effective_from date NOT NULL,
  effective_until date,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PUBLISHED','SUPERSEDED')),
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_layout_profile ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_layout_profile FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_layout_profile AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_layout_profile AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_layout_profile ADD CONSTRAINT document_layout_profile_range_chk CHECK (effective_until IS NULL OR effective_until > effective_from);
ALTER TABLE document_layout_profile ADD CONSTRAINT document_layout_profile_sod_chk CHECK (approved_by IS NULL OR approved_by <> created_by);
CREATE UNIQUE INDEX document_layout_profile_code_rev_uq ON document_layout_profile (tenant_id, profile_code, revision);

-- DOC: document_template — mẫu văn bản/biểu mẫu là dữ liệu: căn cứ pháp lý, mã biểu mẫu, hiệu lực, trạng thái xác nhận pháp lý, nội dung có tham số
CREATE TABLE document_template (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  template_code text NOT NULL,
  revision integer NOT NULL CHECK (revision > 0),
  group_code text NOT NULL CHECK (group_code IN ('DECISION','OFFICIAL_LETTER','REPORT_DISBURSEMENT','REPORT_MONITORING','TREASURY_FORM','SETTLEMENT_FORM','AUDIT_FOLLOWUP','OTHER')),
  doc_type_code text NOT NULL,
  form_code text,
  title text NOT NULL,
  source_module text,
  layout_profile_id uuid NOT NULL,
  body_blocks jsonb NOT NULL,
  placeholder_schema jsonb NOT NULL,
  legal_basis text NOT NULL,
  legal_confirmation_ref text,
  confirmation_status text NOT NULL DEFAULT 'PENDING_CONFIRMATION' CHECK (confirmation_status IN ('CONFIRMED','PENDING_CONFIRMATION')),
  watermark_text text,
  origin text NOT NULL DEFAULT 'PLATFORM_PACK' CHECK (origin IN ('PLATFORM_PACK','TENANT')),
  pack_version text,
  content_sha256 char(64) NOT NULL,
  effective_from date NOT NULL,
  effective_until date,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_REVIEW','PUBLISHED','SUPERSEDED','RETIRED')),
  approved_by uuid,
  legal_confirmed_by uuid,
  legal_confirmed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_template ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_template FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_template AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_template AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_template ADD CONSTRAINT document_template_range_chk CHECK (effective_until IS NULL OR effective_until > effective_from);
ALTER TABLE document_template ADD CONSTRAINT document_template_sod_chk CHECK (approved_by IS NULL OR approved_by <> created_by);
ALTER TABLE document_template ADD CONSTRAINT document_template_watermark_chk CHECK (confirmation_status = 'CONFIRMED' OR watermark_text IS NOT NULL);
ALTER TABLE document_template ADD CONSTRAINT document_template_confirm_chk CHECK (confirmation_status <> 'CONFIRMED' OR (legal_confirmation_ref IS NOT NULL AND legal_confirmed_by IS NOT NULL AND legal_confirmed_at IS NOT NULL));
CREATE UNIQUE INDEX document_template_code_rev_uq ON document_template (tenant_id, template_code, revision);
ALTER TABLE document_template ADD CONSTRAINT document_template_range_excl EXCLUDE USING gist (tenant_id WITH =, template_code WITH =, daterange(effective_from, effective_until, '[)') WITH &&) WHERE (status = 'PUBLISHED');

-- DOC: document_number_register — sổ đăng ký cấp số theo tổ chức × năm dương lịch; hàng bị khóa FOR UPDATE khi cấp số (P3)
CREATE TABLE document_number_register (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  register_code text NOT NULL,
  name text NOT NULL,
  direction text NOT NULL CHECK (direction IN ('OUTGOING','INCOMING')),
  organization_unit_id uuid NOT NULL,
  year integer NOT NULL CHECK (year BETWEEN 2000 AND 2200),
  mode text NOT NULL DEFAULT 'MANAGED' CHECK (mode IN ('MANAGED','MIRRORED')),
  last_number integer NOT NULL DEFAULT 0 CHECK (last_number >= 0),
  status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')),
  closed_at timestamptz,
  scope_policy jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_number_register ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_number_register FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_number_register AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_number_register AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_number_register ADD CONSTRAINT document_number_register_closed_chk CHECK (status = 'OPEN' OR closed_at IS NOT NULL);
CREATE UNIQUE INDEX document_number_register_register_uq ON document_number_register (tenant_id, register_code, organization_unit_id, year);

-- DOC: document_number_allocation — nhật ký bất biến mọi số đã cấp (kể cả số bị hủy); không bao giờ tái sử dụng số
CREATE TABLE document_number_allocation (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  register_id uuid NOT NULL,
  number integer NOT NULL CHECK (number > 0),
  symbol text NOT NULL,
  document_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'ALLOCATED' CHECK (status IN ('ALLOCATED','VOIDED')),
  allocated_at timestamptz NOT NULL DEFAULT now(),
  allocated_by uuid NOT NULL,
  voided_at timestamptz,
  voided_by uuid,
  void_reason text,
  void_approved_by uuid,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_number_allocation ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_number_allocation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_number_allocation AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_number_allocation AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_number_allocation ADD CONSTRAINT document_number_allocation_void_chk CHECK (status = 'ALLOCATED' OR (voided_at IS NOT NULL AND void_reason IS NOT NULL AND void_approved_by IS NOT NULL AND void_approved_by <> allocated_by));
CREATE UNIQUE INDEX document_number_allocation_number_uq ON document_number_allocation (tenant_id, register_id, number);
CREATE UNIQUE INDEX document_number_allocation_document_uq ON document_number_allocation (tenant_id, document_id) WHERE status = 'ALLOCATED';

-- DOC: outgoing_document — quy trình văn bản đi: dự thảo → ký lãnh đạo → cấp số → ký số cơ quan → phát hành
CREATE TABLE outgoing_document (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  document_id uuid NOT NULL,
  template_id uuid,
  layout_profile_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_REVIEW','SUBMITTED','SIGNED','NUMBERED','SEALED','ISSUED','DELIVERED','ACKNOWLEDGED','FILED','ARCHIVED','CANCELLED','RECALLED','REPLACED','CORRECTED')),
  route text NOT NULL DEFAULT 'IN_SYSTEM' CHECK (route IN ('IN_SYSTEM','EXTERNAL_UPLOAD')),
  urgency text NOT NULL DEFAULT 'NORMAL' CHECK (urgency IN ('NORMAL','KHAN','THUONG_KHAN','HOA_TOC')),
  circulation text NOT NULL DEFAULT 'INTERNAL_CIRCULATION' CHECK (circulation IN ('PUBLIC','INTERNAL_CIRCULATION')),
  drafting_unit_id uuid NOT NULL,
  drafter_user_id uuid NOT NULL,
  signer_user_id uuid,
  signer_title text,
  signing_mode text NOT NULL DEFAULT 'DIRECT' CHECK (signing_mode IN ('DIRECT','KT','TM','TL','TUQ')),
  delegation_id uuid,
  clerk_user_id uuid,
  register_id uuid,
  allocation_id uuid,
  recipients jsonb NOT NULL DEFAULT '[]',
  payload_json jsonb,
  payload_sha256 char(64),
  source_module text,
  source_ref text,
  issue_request_id uuid,
  workflow_instance_id uuid,
  reply_to_incoming_id uuid,
  review_due_on date,
  leader_signed_at timestamptz,
  numbered_at timestamptz,
  sealed_at timestamptz,
  issued_at timestamptz,
  unconfirmed_override_reason text,
  unconfirmed_override_by uuid,
  cancel_reason text,
  recall_reason text,
  recalled_at timestamptz,
  recalled_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE outgoing_document ENABLE ROW LEVEL SECURITY;
ALTER TABLE outgoing_document FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON outgoing_document AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON outgoing_document AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_issued_chk CHECK (status NOT IN ('ISSUED','DELIVERED','ACKNOWLEDGED','FILED','ARCHIVED') OR (allocation_id IS NOT NULL AND issued_at IS NOT NULL AND sealed_at IS NOT NULL));
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_numbered_chk CHECK (status NOT IN ('NUMBERED','SEALED') OR (allocation_id IS NOT NULL AND numbered_at IS NOT NULL AND leader_signed_at IS NOT NULL));
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_order_chk CHECK (numbered_at IS NULL OR leader_signed_at IS NULL OR numbered_at >= leader_signed_at);
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_recall_chk CHECK (status <> 'RECALLED' OR (recall_reason IS NOT NULL AND recalled_at IS NOT NULL AND recalled_by IS NOT NULL));
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_cancel_chk CHECK (status <> 'CANCELLED' OR cancel_reason IS NOT NULL);
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_unconfirmed_chk CHECK (unconfirmed_override_reason IS NULL OR (length(unconfirmed_override_reason) >= 20 AND unconfirmed_override_by IS NOT NULL));
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_mode_chk CHECK (signing_mode = 'DIRECT' OR delegation_id IS NOT NULL);
ALTER TABLE outgoing_document ADD CONSTRAINT outgoing_document_source_chk CHECK ((source_module IS NULL) = (source_ref IS NULL));
CREATE UNIQUE INDEX outgoing_document_document_uq ON outgoing_document (tenant_id, document_id);

-- DOC: incoming_document — văn bản đến: tiếp nhận → đăng ký số đến → phân công → xử lý → giải quyết → lưu hồ sơ
CREATE TABLE incoming_document (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  document_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','REGISTERED','ASSIGNED','PROCESSING','RESOLVED','FILED','REJECTED')),
  channel text NOT NULL CHECK (channel IN ('PAPER_SCAN','EMAIL','LGSP','PORTAL','UPLOAD','SYSTEM')),
  received_at timestamptz NOT NULL,
  received_by uuid NOT NULL,
  register_id uuid,
  original_symbol text,
  original_issued_on date,
  sender_name text NOT NULL,
  urgency text NOT NULL DEFAULT 'NORMAL' CHECK (urgency IN ('NORMAL','KHAN','THUONG_KHAN','HOA_TOC')),
  due_on date,
  leader_directive text,
  assigned_unit_id uuid,
  assignee_user_id uuid,
  assigned_by uuid,
  resolution_summary text,
  resolved_at timestamptz,
  response_outgoing_id uuid,
  interop_message_id uuid,
  duplicate_of_id uuid,
  duplicate_override_reason text,
  rejection_reason text,
  is_overdue boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE incoming_document ENABLE ROW LEVEL SECURITY;
ALTER TABLE incoming_document FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON incoming_document AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON incoming_document AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE incoming_document ADD CONSTRAINT incoming_document_assigned_chk CHECK (status NOT IN ('ASSIGNED','PROCESSING','RESOLVED','FILED') OR (assigned_unit_id IS NOT NULL AND assigned_by IS NOT NULL));
ALTER TABLE incoming_document ADD CONSTRAINT incoming_document_resolved_chk CHECK (status NOT IN ('RESOLVED','FILED') OR (resolved_at IS NOT NULL AND resolution_summary IS NOT NULL));
ALTER TABLE incoming_document ADD CONSTRAINT incoming_document_reject_chk CHECK (status <> 'REJECTED' OR rejection_reason IS NOT NULL);
ALTER TABLE incoming_document ADD CONSTRAINT incoming_document_registered_chk CHECK (status IN ('RECEIVED','REJECTED') OR register_id IS NOT NULL);
CREATE UNIQUE INDEX incoming_document_document_uq ON incoming_document (tenant_id, document_id);
CREATE UNIQUE INDEX incoming_document_dup_uq ON incoming_document (tenant_id, sender_name, original_symbol, original_issued_on) WHERE original_symbol IS NOT NULL AND original_issued_on IS NOT NULL AND status <> 'REJECTED' AND duplicate_override_reason IS NULL;

-- DOC: document_signature — kết quả xác minh từng chữ ký số trong phiên bản PDF (SignatureVerification); mỗi lần xác minh lại là một dòng mới
CREATE TABLE document_signature (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  document_version_id uuid NOT NULL,
  verification_no integer NOT NULL DEFAULT 1 CHECK (verification_no > 0),
  signature_index integer NOT NULL CHECK (signature_index >= 0),
  role text NOT NULL CHECK (role IN ('LEADER','ORGANIZATION','EXTERNAL','DOCUMENT_TIMESTAMP')),
  signing_certificate_id uuid,
  cert_subject_dn text,
  cert_issuer_dn text,
  cert_serial text,
  cert_fingerprint_sha256 char(64),
  trust_regime text CHECK (trust_regime IN ('PUBLIC_CA','GOV_SPECIALIZED')),
  profile text CHECK (profile IN ('PADES_B_B','PADES_B_T','PADES_B_LT','PADES_B_LTA')),
  docmdp_level integer CHECK (docmdp_level IS NULL OR docmdp_level IN (1,2,3)),
  byte_range jsonb,
  covers_end_offset bigint,
  signed_at timestamptz,
  timestamp_at timestamptz,
  verification_status text NOT NULL CHECK (verification_status IN ('VALID','INVALID','INDETERMINATE','NOT_VERIFIED')),
  chain_status text NOT NULL DEFAULT 'NOT_CHECKED' CHECK (chain_status IN ('TRUSTED','UNTRUSTED','INCOMPLETE','NOT_CHECKED')),
  revocation_status text NOT NULL DEFAULT 'NOT_CHECKED' CHECK (revocation_status IN ('GOOD','REVOKED','UNKNOWN','NOT_CHECKED')),
  incremental_changes_allowed boolean,
  failure_codes jsonb NOT NULL DEFAULT '[]',
  verified_at timestamptz NOT NULL DEFAULT now(),
  verifier_version text NOT NULL,
  report_object_key text,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_signature ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_signature FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_signature AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_signature AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE UNIQUE INDEX document_signature_sig_uq ON document_signature (tenant_id, document_version_id, verification_no, signature_index);

-- DOC: doc_signing_session — phiên ký hai pha (chuẩn bị băm → CA ký → nhúng CMS) qua adapter ký số
CREATE TABLE doc_signing_session (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  outgoing_document_id uuid NOT NULL,
  role text NOT NULL CHECK (role IN ('LEADER','ORGANIZATION')),
  signer_user_id uuid,
  signing_certificate_id uuid,
  adapter_code text NOT NULL CHECK (adapter_code IN ('REMOTE_CA','LOCAL_AGENT','MOCK')),
  adapter_status text NOT NULL CHECK (adapter_status IN ('VERIFIED','PROPOSED','MOCK','MISSING')),
  status text NOT NULL DEFAULT 'CREATED' CHECK (status IN ('CREATED','HASH_READY','AWAITING_SIGNER','SIGNED','EMBEDDED','FAILED','EXPIRED','CANCELLED')),
  base_version_id uuid NOT NULL,
  result_version_id uuid,
  digest_algorithm text NOT NULL DEFAULT 'SHA-256',
  digest_hex char(64),
  byte_range jsonb,
  provider_txn_ref text,
  expires_at timestamptz NOT NULL,
  attempts integer NOT NULL DEFAULT 0,
  error_code text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE doc_signing_session ENABLE ROW LEVEL SECURITY;
ALTER TABLE doc_signing_session FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON doc_signing_session AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON doc_signing_session AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE doc_signing_session ADD CONSTRAINT doc_signing_session_embedded_chk CHECK (status <> 'EMBEDDED' OR result_version_id IS NOT NULL);
CREATE UNIQUE INDEX doc_signing_session_open_uq ON doc_signing_session (tenant_id, outgoing_document_id, role) WHERE status IN ('CREATED','HASH_READY','AWAITING_SIGNER','SIGNED');

-- DOC: document_distribution — phân phối văn bản đi tới từng nơi nhận và xác nhận đã nhận
CREATE TABLE document_distribution (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  outgoing_document_id uuid NOT NULL,
  recipient_kind text NOT NULL CHECK (recipient_kind IN ('INTERNAL_UNIT','EXTERNAL_AGENCY','PERSON')),
  recipient_unit_id uuid,
  recipient_name text NOT NULL,
  recipient_code text,
  channel text NOT NULL CHECK (channel IN ('INTERNAL','LGSP','EMAIL','PAPER_HANDOVER')),
  status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','DELIVERED','ACKNOWLEDGED','FAILED','CANCELLED')),
  sent_at timestamptz,
  delivered_at timestamptz,
  acknowledged_at timestamptz,
  external_ref text,
  attempts integer NOT NULL DEFAULT 0,
  error_code text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_distribution ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_distribution FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_distribution AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_distribution AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_distribution ADD CONSTRAINT document_distribution_ack_chk CHECK (status <> 'ACKNOWLEDGED' OR acknowledged_at IS NOT NULL);
CREATE UNIQUE INDEX document_distribution_recipient_uq ON document_distribution (tenant_id, outgoing_document_id, recipient_name, channel);

-- DOC: document_relation — quan hệ giữa các văn bản: thay thế, đính chính, thu hồi, căn cứ, trả lời
CREATE TABLE document_relation (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  from_document_id uuid NOT NULL,
  to_document_id uuid NOT NULL,
  relation_kind text NOT NULL CHECK (relation_kind IN ('REPLACES','CORRECTS','RECALLS','BASED_ON','RESPONDS_TO','ATTACHES')),
  note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE document_relation ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_relation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON document_relation AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON document_relation AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE document_relation ADD CONSTRAINT document_relation_self_chk CHECK (from_document_id <> to_document_id);
CREATE UNIQUE INDEX document_relation_relation_uq ON document_relation (tenant_id, from_document_id, to_document_id, relation_kind);

-- DOC: dossier — hồ sơ (hồ sơ công việc/hồ sơ dự án) theo Luật Lưu trữ 33/2024
CREATE TABLE dossier (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  dossier_code text NOT NULL,
  year integer NOT NULL,
  title text NOT NULL,
  organization_unit_id uuid NOT NULL,
  subject_module text,
  subject_id uuid,
  category_code text NOT NULL,
  retention_rule_id uuid,
  retention_class_code text,
  status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED','HANDED_OVER','ARCHIVED','DISPOSAL_PROPOSED','DISPOSED')),
  closed_at timestamptz,
  handover_due_on date,
  handed_over_at timestamptz,
  archive_ref text,
  disposal_decision_document_id uuid,
  provisional_retention boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
