CREATE POLICY tenant_boundary ON dossier AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE dossier ADD CONSTRAINT dossier_closed_chk CHECK (status = 'OPEN' OR closed_at IS NOT NULL);
ALTER TABLE dossier ADD CONSTRAINT dossier_disposed_chk CHECK (status <> 'DISPOSED' OR (disposal_decision_document_id IS NOT NULL AND provisional_retention = false));
CREATE UNIQUE INDEX dossier_code_uq ON dossier (tenant_id, dossier_code, year);

-- DOC: dossier_item — tài liệu nằm trong hồ sơ
CREATE TABLE dossier_item (
  tenant_id uuid NOT NULL,
