ALTER TABLE dossier_item ENABLE ROW LEVEL SECURITY;
ALTER TABLE dossier_item FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON dossier_item AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON dossier_item AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE UNIQUE INDEX dossier_item_item_uq ON dossier_item (tenant_id, dossier_id, document_id);
CREATE UNIQUE INDEX dossier_item_ordinal_uq ON dossier_item (tenant_id, dossier_id, ordinal);

-- DOC: doc_retention_rule — RetentionPolicy là dữ liệu: thời hạn bảo quản theo nhóm hồ sơ, căn cứ TT 74/2025/TT-BTC hoặc TT 10/2022/TT-BNV [CXN-05]
CREATE TABLE doc_retention_rule (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  rule_set text NOT NULL CHECK (rule_set IN ('TT74_2025_BTC','TT10_2022_BNV','TENANT_CUSTOM')),
  category_code text NOT NULL,
  class_code text NOT NULL CHECK (class_code IN ('PERMANENT','Y70','Y20','Y10','Y5')),
  retention_years integer CHECK (retention_years IS NULL OR retention_years > 0),
  start_basis text NOT NULL CHECK (start_basis IN ('FROM_CLOSED','FROM_SETTLEMENT','FROM_ISSUED')),
  handover_months integer NOT NULL DEFAULT 12 CHECK (handover_months >= 0),
  end_action text NOT NULL DEFAULT 'REVIEW_FOR_DISPOSAL' CHECK (end_action IN ('REVIEW_FOR_DISPOSAL','TRANSFER_TO_NATIONAL_ARCHIVE')),
  legal_basis text NOT NULL,
  legal_confirmation_ref text,
  confirmation_status text NOT NULL DEFAULT 'PENDING_CONFIRMATION' CHECK (confirmation_status IN ('CONFIRMED','PENDING_CONFIRMATION')),
  precedence integer NOT NULL DEFAULT 100,
  effective_from date NOT NULL,
  effective_until date,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PUBLISHED','SUPERSEDED')),
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE doc_retention_rule ENABLE ROW LEVEL SECURITY;
ALTER TABLE doc_retention_rule FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON doc_retention_rule AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON doc_retention_rule AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE doc_retention_rule ADD CONSTRAINT doc_retention_rule_perm_chk CHECK ((class_code = 'PERMANENT') = (retention_years IS NULL));
ALTER TABLE doc_retention_rule ADD CONSTRAINT doc_retention_rule_range_chk CHECK (effective_until IS NULL OR effective_until > effective_from);
ALTER TABLE doc_retention_rule ADD CONSTRAINT doc_retention_rule_sod_chk CHECK (approved_by IS NULL OR approved_by <> created_by);
CREATE UNIQUE INDEX doc_retention_rule_rule_uq ON doc_retention_rule (tenant_id, rule_set, category_code, effective_from);

-- DOC: doc_interop_message — thông điệp liên thông văn bản qua LGSP của cơ quan khách hàng (QĐ 28/2018, QCVN 102:2016) — adapter PROPOSED [CXN-06]
CREATE TABLE doc_interop_message (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  direction text NOT NULL CHECK (direction IN ('OUTBOUND','INBOUND')),
  document_id uuid,
  adapter_code text NOT NULL DEFAULT 'LGSP_EDXML',
  adapter_status text NOT NULL DEFAULT 'PROPOSED' CHECK (adapter_status IN ('VERIFIED','PROPOSED','MOCK','MISSING')),
  external_message_id text,
  sender_code text,
  receiver_code text,
  envelope_sha256 char(64) NOT NULL,
  envelope_object_key text NOT NULL,
  status text NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED','SENT','ACKED','REJECTED','FAILED','DEAD','RECEIVED','PROCESSED')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 20),
  next_attempt_at timestamptz,
  error_code text,
  processed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE doc_interop_message ENABLE ROW LEVEL SECURITY;
ALTER TABLE doc_interop_message FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON doc_interop_message AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON doc_interop_message AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE UNIQUE INDEX doc_interop_message_ext_uq ON doc_interop_message (tenant_id, direction, external_message_id) WHERE external_message_id IS NOT NULL;
CREATE UNIQUE INDEX doc_interop_message_hash_uq ON doc_interop_message (tenant_id, direction, envelope_sha256) WHERE direction = 'INBOUND';

-- DOC: doc_issue_request — yêu cầu phát hành từ module nghiệp vụ (MNE, DIS, CAP, PAY, PRJ, BID, AUD) — hợp đồng sự kiện issue_requested → issued/rejected/recalled
CREATE TABLE doc_issue_request (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  source_module text NOT NULL,
  source_ref text NOT NULL,
  template_code text NOT NULL,
  template_id uuid,
  payload_sha256 char(64) NOT NULL,
  payload_ref text NOT NULL,
  event_id uuid NOT NULL,
  signer_hint jsonb,
  recipients_hint jsonb,
  status text NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','ACCEPTED','REJECTED','ISSUED','CANCELLED','RECALLED')),
  reject_code text,
  outgoing_document_id uuid,
  requested_by uuid NOT NULL,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE doc_issue_request ENABLE ROW LEVEL SECURITY;
ALTER TABLE doc_issue_request FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON doc_issue_request AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON doc_issue_request AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE doc_issue_request ADD CONSTRAINT doc_issue_request_reject_chk CHECK (status <> 'REJECTED' OR reject_code IS NOT NULL);
ALTER TABLE doc_issue_request ADD CONSTRAINT doc_issue_request_hash_chk CHECK (payload_sha256 ~ '^[0-9a-f]{64}$');
CREATE UNIQUE INDEX doc_issue_request_event_uq ON doc_issue_request (tenant_id, source_module, event_id);
CREATE UNIQUE INDEX doc_issue_request_open_uq ON doc_issue_request (tenant_id, source_module, source_ref, payload_sha256) WHERE status IN ('RECEIVED','ACCEPTED','ISSUED');

-- AUD: audit_engagement — cuộc thanh tra/kiểm toán/kiểm tra (Luật Thanh tra 84/2025, Luật KTNN)
CREATE TABLE audit_engagement (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
