  started_on date,
  fieldwork_ended_on date,
  closed_on date,
  legal_hold_id uuid,
  classification text NOT NULL DEFAULT 'CONFIDENTIAL' CHECK (classification IN ('INTERNAL','CONFIDENTIAL')),
  cancel_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE audit_engagement ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_engagement FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON audit_engagement AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON audit_engagement AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE audit_engagement ADD CONSTRAINT audit_engagement_period_chk CHECK (period_to >= period_from);
ALTER TABLE audit_engagement ADD CONSTRAINT audit_engagement_closed_chk CHECK (status <> 'CLOSED' OR closed_on IS NOT NULL);
ALTER TABLE audit_engagement ADD CONSTRAINT audit_engagement_cancel_chk CHECK (status <> 'CANCELLED' OR cancel_reason IS NOT NULL);
