CREATE POLICY tenant_boundary ON audit_scope_item AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE audit_scope_item ADD CONSTRAINT audit_scope_item_kind_chk CHECK ((scope_kind = 'UNIT' AND organization_unit_id IS NOT NULL) OR (scope_kind = 'PROJECT' AND project_id IS NOT NULL) OR (scope_kind = 'CONTRACT' AND contract_id IS NOT NULL));
CREATE UNIQUE INDEX audit_scope_item_scope_uq ON audit_scope_item (tenant_id, engagement_id, scope_kind, organization_unit_id, project_id, contract_id);

-- AUD: audit_conclusion — kết luận thanh tra / báo cáo kiểm toán / thông báo kết quả kiểm toán đã nhận
CREATE TABLE audit_conclusion (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  engagement_id uuid NOT NULL,
  conclusion_kind text NOT NULL CHECK (conclusion_kind IN ('INSPECTION_CONCLUSION','AUDIT_REPORT','AUDIT_NOTICE','INTERNAL_REPORT')),
  conclusion_document_id uuid NOT NULL,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  supersedes_id uuid,
  issued_on date NOT NULL,
  received_on date NOT NULL,
  implementation_due_on date,
  report_due_on date,
  summary text NOT NULL,
  total_financial_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (total_financial_vnd >= 0),
  is_public boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','ANALYSED','SUPERSEDED','CLOSED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE audit_conclusion ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_conclusion FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON audit_conclusion AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON audit_conclusion AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE audit_conclusion ADD CONSTRAINT audit_conclusion_date_chk CHECK (received_on >= issued_on);
ALTER TABLE audit_conclusion ADD CONSTRAINT audit_conclusion_rev_chk CHECK (revision = 1 OR supersedes_id IS NOT NULL);
CREATE UNIQUE INDEX audit_conclusion_rev_uq ON audit_conclusion (tenant_id, engagement_id, conclusion_kind, revision);

-- AUD: audit_finding — phát hiện/sai phạm trong kết luận
CREATE TABLE audit_finding (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  conclusion_id uuid NOT NULL,
  finding_code text NOT NULL,
  category text NOT NULL CHECK (category IN ('FINANCIAL','PROCEDURE','PROCUREMENT','QUALITY','LAND','PLANNING','OTHER')),
  project_id uuid,
  contract_id uuid,
  organization_unit_id uuid,
  description text NOT NULL,
  legal_basis_cited text,
  amount_vnd numeric(24,0) CHECK (amount_vnd IS NULL OR amount_vnd >= 0),
  severity text NOT NULL DEFAULT 'MEDIUM' CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE audit_finding ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_finding FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON audit_finding AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON audit_finding AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE UNIQUE INDEX audit_finding_code_uq ON audit_finding (tenant_id, conclusion_id, finding_code);

-- AUD: audit_recommendation — kiến nghị/yêu cầu xử lý: tài chính (thu hồi, giảm trừ) hoặc quy trình, có owner, hạn, trạng thái
CREATE TABLE audit_recommendation (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  conclusion_id uuid NOT NULL,
  finding_id uuid,
  rec_code text NOT NULL,
  rec_type text NOT NULL CHECK (rec_type IN ('FINANCIAL_RECOVERY','FINANCIAL_ADJUSTMENT','PROCESS_CORRECTION','ACCOUNTABILITY','REFERRAL','POLICY_CHANGE')),
  description text NOT NULL,
  amount_vnd numeric(24,0) CHECK (amount_vnd IS NULL OR amount_vnd > 0),
  recovered_vnd numeric(24,0) NOT NULL DEFAULT 0 CHECK (recovered_vnd >= 0),
  project_id uuid,
  owner_unit_id uuid,
  owner_user_id uuid,
  due_on date,
  status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ASSIGNED','IN_PROGRESS','PENDING_VERIFICATION','CLOSED','DISPUTED','CANCELLED')),
  is_overdue boolean NOT NULL DEFAULT false,
  linked_issue_id uuid,
  dispute_reason text,
  dispute_document_id uuid,
  dispute_outcome text CHECK (dispute_outcome IN ('ACCEPTED_BY_AUTHORITY','REJECTED_BY_AUTHORITY')),
  closure_basis_document_id uuid,
  submitted_by uuid,
  verified_by uuid,
  verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE audit_recommendation ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_recommendation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON audit_recommendation AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON audit_recommendation AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE audit_recommendation ADD CONSTRAINT audit_recommendation_fin_amount_chk CHECK (rec_type NOT IN ('FINANCIAL_RECOVERY','FINANCIAL_ADJUSTMENT') OR amount_vnd IS NOT NULL);
ALTER TABLE audit_recommendation ADD CONSTRAINT audit_recommendation_recovery_chk CHECK (amount_vnd IS NULL OR recovered_vnd <= amount_vnd);
ALTER TABLE audit_recommendation ADD CONSTRAINT audit_recommendation_assign_chk CHECK (status IN ('OPEN','CANCELLED') OR (owner_unit_id IS NOT NULL AND due_on IS NOT NULL));
ALTER TABLE audit_recommendation ADD CONSTRAINT audit_recommendation_close_chk CHECK (status <> 'CLOSED' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL AND (submitted_by IS NULL OR verified_by <> submitted_by)));
ALTER TABLE audit_recommendation ADD CONSTRAINT audit_recommendation_fin_close_chk CHECK (status <> 'CLOSED' OR rec_type NOT IN ('FINANCIAL_RECOVERY','FINANCIAL_ADJUSTMENT') OR recovered_vnd = amount_vnd OR dispute_outcome = 'ACCEPTED_BY_AUTHORITY');
ALTER TABLE audit_recommendation ADD CONSTRAINT audit_recommendation_dispute_chk CHECK (status <> 'DISPUTED' OR dispute_reason IS NOT NULL);
CREATE UNIQUE INDEX audit_recommendation_code_uq ON audit_recommendation (tenant_id, conclusion_id, rec_code);

-- AUD: audit_remediation_action — hành động khắc phục của owner cho một kiến nghị
CREATE TABLE audit_remediation_action (
