  completed_on date,
  status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','DONE','CANCELLED')),
  evidence_document_id uuid,
  reported_by uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE audit_remediation_action ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_remediation_action FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON audit_remediation_action AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON audit_remediation_action AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE audit_remediation_action ADD CONSTRAINT audit_remediation_action_done_chk CHECK (status <> 'DONE' OR (completed_on IS NOT NULL AND evidence_document_id IS NOT NULL));
CREATE UNIQUE INDEX audit_remediation_action_code_uq ON audit_remediation_action (tenant_id, recommendation_id, action_code);

-- AUD: audit_recovery_link — liên kết kiến nghị tài chính ↔ khoản thu hồi/giảm trừ ở PAY (sổ lũy kế, chỉ thêm, đảo bằng dòng âm)
CREATE TABLE audit_recovery_link (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  recommendation_id uuid NOT NULL,
  source_kind text NOT NULL CHECK (source_kind IN ('PAY_RECOVERY','PAY_DEDUCTION','TREASURY_REMITTANCE','MANUAL_EVIDENCE')),
  source_id uuid,
  source_event_id uuid,
  amount_vnd numeric(24,0) NOT NULL CHECK (amount_vnd <> 0),
  recorded_on date NOT NULL,
  evidence_document_id uuid,
  reversal_of_id uuid,
  recorded_by uuid NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE audit_recovery_link ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_recovery_link FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON audit_recovery_link AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON audit_recovery_link AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE audit_recovery_link ADD CONSTRAINT audit_recovery_link_reversal_chk CHECK ((amount_vnd < 0) = (reversal_of_id IS NOT NULL));
ALTER TABLE audit_recovery_link ADD CONSTRAINT audit_recovery_link_manual_chk CHECK (source_kind <> 'MANUAL_EVIDENCE' OR evidence_document_id IS NOT NULL);
