CREATE POLICY tenant_boundary ON document_page_ocr AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
