  data_agreement_document_id uuid,
  d07_approval_ref text,
  adapter_status text NOT NULL DEFAULT 'PROPOSED' CHECK (adapter_status IN ('VERIFIED','PROPOSED','MOCK','MISSING')),
  status text NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED','ACTIVE','SUSPENDED','RETIRED')),
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
