ALTER TABLE ai_provider ADD CONSTRAINT ai_provider_intl_chk CHECK (route_class <> 'INTERNATIONAL' OR (max_classification = 'PUBLIC' AND (status <> 'ACTIVE' OR d07_approval_ref IS NOT NULL)));
ALTER TABLE ai_provider ADD CONSTRAINT ai_provider_vn_chk CHECK (route_class = 'INTERNATIONAL' OR region_country = 'VN');
CREATE UNIQUE INDEX ai_provider_code_uq ON ai_provider (tenant_id, provider_code);

