-- LLM: ai_request — envelope mọi yêu cầu AI: phân loại, căn cứ phân loại, tuyến, chính sách, ngân sách, kết quả (audit tuyến)
CREATE TABLE ai_request (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  task_type text NOT NULL,
  subject_module text NOT NULL,
  subject_id uuid,
  requested_by uuid NOT NULL,
  profile_version_id uuid NOT NULL,
  prompt_version_id uuid,
  data_classification text NOT NULL CHECK (data_classification IN ('PUBLIC','INTERNAL','CONFIDENTIAL','PERSONAL','IMPORTANT_CORE')),
  classification_basis jsonb NOT NULL,
  anonymisation_attestation_id uuid,
  policy_version_id uuid NOT NULL,
  route_class text CHECK (route_class IN ('DOMESTIC_HOSTED','SELF_HOSTED','INTERNATIONAL')),
  provider_id uuid,
  model_ref_id uuid,
  status text NOT NULL DEFAULT 'ADMITTED' CHECK (status IN ('ADMITTED','REJECTED_POLICY','RESERVED','DISPATCHED','COMPLETED','FAILED','CANCELLED','REJECTED_NO_CITATION','PENDING_RECONCILE')),
  reject_code text,
  input_sha256 char(64) NOT NULL,
  output_sha256 char(64),
  citations_count integer,
  budget_reservation_id uuid,
  cost_vnd numeric(24,0),
  langfuse_trace_id text,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE ai_request ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_request FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON ai_request AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON ai_request AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE ai_request ADD CONSTRAINT ai_request_route_chk CHECK (status IN ('ADMITTED','REJECTED_POLICY') OR route_class IS NOT NULL);
ALTER TABLE ai_request ADD CONSTRAINT ai_request_intl_chk CHECK (route_class IS DISTINCT FROM 'INTERNATIONAL' OR data_classification = 'PUBLIC');
ALTER TABLE ai_request ADD CONSTRAINT ai_request_reject_chk CHECK (status NOT IN ('REJECTED_POLICY','REJECTED_NO_CITATION') OR reject_code IS NOT NULL);

-- LLM: ai_budget — hạn mức chi phí và quota AI theo tenant/đơn vị/dự án/người dùng
CREATE TABLE ai_budget (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  scope_kind text NOT NULL CHECK (scope_kind IN ('TENANT','UNIT','PROJECT','USER')),
  scope_ref_id uuid,
  period text NOT NULL DEFAULT 'MONTH' CHECK (period IN ('MONTH','QUARTER','YEAR')),
  limit_vnd numeric(24,0) NOT NULL CHECK (limit_vnd >= 0),
  soft_threshold_pct integer NOT NULL DEFAULT 80 CHECK (soft_threshold_pct BETWEEN 1 AND 100),
  hard_stop boolean NOT NULL DEFAULT true,
  max_requests_per_day integer,
  max_concurrent integer,
  effective_from date NOT NULL,
  status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','RETIRED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE ai_budget ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_budget FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON ai_budget AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON ai_budget AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE ai_budget ADD CONSTRAINT ai_budget_scope_chk CHECK ((scope_kind = 'TENANT') = (scope_ref_id IS NULL));
CREATE UNIQUE INDEX ai_budget_scope_uq ON ai_budget (tenant_id, scope_kind, scope_ref_id, period) WHERE status = 'ACTIVE';

-- LLM: ai_budget_counter — bộ đếm theo kỳ; khóa FOR UPDATE theo thứ tự tenant→unit→project→user khi đặt chỗ
CREATE TABLE ai_budget_counter (
