  limit_vnd numeric(24,0) NOT NULL,
  settled_vnd numeric(24,8) NOT NULL DEFAULT 0,
  reserved_open_vnd numeric(24,8) NOT NULL DEFAULT 0,
  request_count integer NOT NULL DEFAULT 0,
  exception_count integer NOT NULL DEFAULT 0,
  blocked boolean NOT NULL DEFAULT false,
  version bigint NOT NULL DEFAULT 1,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE ai_budget_counter ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_budget_counter FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON ai_budget_counter AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON ai_budget_counter AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE ai_budget_counter ADD CONSTRAINT ai_budget_counter_nonneg_chk CHECK (settled_vnd >= 0 AND reserved_open_vnd >= 0);
ALTER TABLE ai_budget_counter ADD CONSTRAINT ai_budget_counter_reserve_chk CHECK (reserved_open_vnd <= limit_vnd);
CREATE UNIQUE INDEX ai_budget_counter_period_uq ON ai_budget_counter (tenant_id, budget_id, period_start);

