CREATE TABLE ai_decision_record (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  ai_request_id uuid NOT NULL,
  subject_module text NOT NULL,
  subject_kind text NOT NULL,
  subject_id uuid NOT NULL,
  ai_output_sha256 char(64) NOT NULL,
  action_kind text NOT NULL CHECK (action_kind IN ('WRITE','MONEY','DECISION','PUBLISH')),
