  state text NOT NULL DEFAULT 'ENGAGED' CHECK (state IN ('ENGAGED','RELEASED')),
  engaged_by uuid NOT NULL,
  engaged_at timestamptz NOT NULL DEFAULT now(),
  release_approved_by uuid,
  released_at timestamptz,
  release_reason text,
  affected_requests integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE ai_kill_switch ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_kill_switch FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON ai_kill_switch AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON ai_kill_switch AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE ai_kill_switch ADD CONSTRAINT ai_kill_switch_release_chk CHECK (state = 'ENGAGED' OR (released_at IS NOT NULL AND release_reason IS NOT NULL AND release_approved_by IS NOT NULL AND release_approved_by <> engaged_by));
CREATE UNIQUE INDEX ai_kill_switch_engaged_uq ON ai_kill_switch (tenant_id, scope_kind, scope_ref) WHERE state = 'ENGAGED';

