-- BI: metric_definition (existing, extended)
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS origin text NOT NULL DEFAULT 'TENANT_UI' CHECK (origin IN ('PLATFORM_CODE','TENANT_UI'));
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS source_commit text;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS definition_sha256 char(64);
