ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS dimension_codes jsonb NOT NULL DEFAULT '[]';
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS dataset_id uuid;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS glossary_term_id uuid;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS legal_basis text;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS effective_from date;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS effective_until date;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS supersedes_id uuid;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS certified_by uuid;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS certified_at timestamptz;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS created_by uuid;
ALTER TABLE metric_definition ADD COLUMN IF NOT EXISTS version bigint NOT NULL DEFAULT 1;
DROP POLICY IF EXISTS tenant_boundary ON metric_definition;
CREATE POLICY tenant_access ON metric_definition AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON metric_definition AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
