ALTER TABLE maturity_rubric_version FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON maturity_rubric_version AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON maturity_rubric_version AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE maturity_rubric_version ADD CONSTRAINT maturity_rubric_version_sod_chk CHECK (approved_by IS NULL OR approved_by <> created_by);
CREATE UNIQUE INDEX maturity_rubric_version_rev_uq ON maturity_rubric_version (tenant_id, rubric_code, revision);

-- DGV: maturity_milestone — lộ trình trưởng thành: mục tiêu mức theo trụ cột, owner, tiêu chí thoát, bằng chứng
CREATE TABLE maturity_milestone (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  rubric_version_id uuid NOT NULL,
  pillar_code text NOT NULL,
  target_level integer NOT NULL CHECK (target_level BETWEEN 1 AND 5),
  due_on date NOT NULL,
  owner_user_id uuid NOT NULL,
  exit_criteria text NOT NULL,
  evidence_required jsonb NOT NULL,
  status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','IN_PROGRESS','ACHIEVED','MISSED')),
  achieved_assessment_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE maturity_milestone ENABLE ROW LEVEL SECURITY;
ALTER TABLE maturity_milestone FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON maturity_milestone AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON maturity_milestone AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE maturity_milestone ADD CONSTRAINT maturity_milestone_achieved_chk CHECK (status <> 'ACHIEVED' OR achieved_assessment_id IS NOT NULL);

-- DGV: data_product — data product được chứng nhận (báo cáo vốn, actual Kho bạc, hồ sơ AI, usage SaaS)
CREATE TABLE data_product (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  code text NOT NULL,
  title text NOT NULL,
  dataset_ids jsonb NOT NULL,
  owner_user_id uuid NOT NULL,
  certification_status text NOT NULL DEFAULT 'NOT_ASSESSED' CHECK (certification_status IN ('NOT_ASSESSED','PROVISIONAL','CERTIFIED','REVOKED')),
  certified_by uuid,
  certified_at timestamptz,
  certification_expires_on date,
  evidence_refs jsonb NOT NULL DEFAULT '[]',
  revoke_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NOT NULL,
  version bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, id)
);
ALTER TABLE data_product ENABLE ROW LEVEL SECURITY;
ALTER TABLE data_product FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON data_product AS PERMISSIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY tenant_boundary ON data_product AS RESTRICTIVE FOR ALL USING (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE data_product ADD CONSTRAINT data_product_cert_chk CHECK (certification_status <> 'CERTIFIED' OR (certified_by IS NOT NULL AND certified_by <> owner_user_id AND certification_expires_on IS NOT NULL));
CREATE UNIQUE INDEX data_product_code_uq ON data_product (tenant_id, code);

